// components/StyledGroupedBarChart.jsx
import React, { useMemo } from "react";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";
import { Bar } from "react-chartjs-2";

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

// numeric parser (keeps naming exactly as in your JSON)
const toNum = (v) => {
  if (v === null || v === undefined) return 0;
  const s = String(v).replace(/,/g, "").trim();
  if (s === "" || s === "-") return 0;
  const n = parseFloat(s);
  return Number.isNaN(n) ? 0 : n;
};

// month index to sort periods like "Mar-23"
const monthIndex = {
  Jan: 1, Feb: 2, Mar: 3, Apr: 4, May: 5, Jun: 6,
  Jul: 7, Aug: 8, Sep: 9, Oct: 10, Nov: 11, Dec: 12,
};
const sortKey = (period) => {
  if (!period) return 0;
  const parts = String(period).split("-");
  const mon = (parts[0] || "").substring(0, 3);
  const yr = (parts[1] || "");
  const y = parseInt(yr.length === 2 ? "20" + yr : yr, 10) || 0;
  const m = monthIndex[mon] || 0;
  return y * 100 + m;
};

export default function StyledGroupedBarChart({ financialData = [], amountType = "In Crores" }) {
  // Keep JSON keys exactly: assets, revenue, net_worth, profit_after_tax, reserves_and_surpluse, total_borrowing, period_ended
  const parsed = useMemo(() => {
    // remove header-like row(s) where period_ended === "Period Ended"
    const rows = (Array.isArray(financialData) ? financialData : []).filter(
      (r) => r && String(r.period_ended).toLowerCase().indexOf("period") === -1
    );

    // sort chronologically
    rows.sort((a, b) => sortKey(a.period_ended) - sortKey(b.period_ended));

    return {
      periods: rows.map((r) => r.period_ended),
      assets: rows.map((r) => toNum(r.assets)),
      revenue: rows.map((r) => toNum(r.revenue)),
      net_worth: rows.map((r) => toNum(r.net_worth)),
      profit_after_tax: rows.map((r) => toNum(r.profit_after_tax)),
      reserves_and_surpluse: rows.map((r) => toNum(r.reserves_and_surpluse)),
      total_borrowing: rows.map((r) => toNum(r.total_borrowing)),
    };
  }, [financialData]);

  // WOW gradient palette aligned with each dataset (keeps label keys intact)
  const COLORS = [
    ["#ffdd87", "#ffb300"],   // assets
    ["#ff9f87", "#ff5b2e"],   // revenue
    ["#82c8ff", "#1f9bff"],   // net_worth
    ["#d0a6ff", "#944dff"],   // profit_after_tax
    ["#94f6d5", "#00d3a9"],   // reserves_and_surpluse
    ["#9df3ff", "#3cdcff"],   // total_borrowing
  ];

  // Build datasets with gradients (ctx provided by react-chartjs-2 when data is a function)
  const buildDatasets = (ctx) => {
    const keys = [
      "assets",
      "revenue",
      "net_worth",
      "profit_after_tax",
      "reserves_and_surpluse",
      "total_borrowing",
    ];

    return keys.map((key, i) => {
      const base = COLORS[i] || ["#ccc", "#999"];
      // default color for SSR or before chartArea available
      let bg = base[0];

      // create gradient if ctx/chartArea available
      if (ctx && ctx.chart && ctx.chart.ctx && ctx.chart.chartArea) {
        const c = ctx.chart.ctx;
        const area = ctx.chart.chartArea;
        const g = c.createLinearGradient(0, area.bottom, 0, area.top);
        g.addColorStop(0, base[0]);
        g.addColorStop(1, base[1]);
        bg = g;
      }

      // label: show friendly label but DO NOT change your keys in data structure
      const label = key
        .replace(/_/g, " ")
        .replace(/\b\w/g, (ch) => ch.toUpperCase());

      return {
        label,
        data: parsed[key],
        backgroundColor: bg,
        borderRadius: 12,
        borderWidth: 1,
        borderColor: "rgba(0,0,0,0.06)",
      };
    });
  };

  // data as function so react-chartjs-2 passes chart context to create gradients
  const dataFn = (ctx) => ({
    labels: parsed?.periods,
    datasets: buildDatasets(ctx),
  });

  // options (polished)
  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: "top",
        labels: {
          usePointStyle: true,
          pointStyle: "rectRounded",
          padding: 14,
          boxWidth: 14,
          boxHeight: 14,
          color: "#222",
        },
      },
      title: {
        display: true,
        text: `Financial Overview (${amountType})`,
        font: { size: 18, weight: "600" },
      },
      tooltip: {
        backgroundColor: "#ffffff",
        titleColor: "#111",
        bodyColor: "#222",
        borderColor: "rgba(0,0,0,0.08)",
        borderWidth: 1,
        padding: 10,
        callbacks: {
          label: (ctx) => {
            const val = ctx.raw;
            return `${ctx.dataset.label}: ${Number(val).toLocaleString()} ${amountType}`;
          },
        },
      },
    },
    scales: {
      x: {
        grid: { display: false },
        ticks: { color: "#333" },
      },
      y: {
        beginAtZero: true,
        grid: { color: "rgba(0,0,0,0.06)", borderDash: [4, 4] },
        ticks: { color: "#333" },
      },
    },
    // scriptable bar thickness via dataset options (Chart.js supports dataset defaults)
    datasets: {
      bar: {
        barThickness: (ctx) => {
          const w = ctx.chart.width || 800;
          if (w < 480) return 10;
          if (w < 768) return 14;
          if (w < 1024) return 20;
          return 28;
        },
      },
    },
  };

  return (
    <div style={{
      width: "100%",
      height: 520,
      padding: 16,
      borderRadius: 12,
      background: "linear-gradient(180deg,#fbfbfd,#ffffff)",
      boxShadow: "0 8px 24px rgba(12,22,40,0.06)",
      border: "1px solid rgba(15,15,15,0.03)"
    }}>
      <Bar data={dataFn} options={options} />
    </div>
  );
}
